package main

import "core:bytes"
import "core:net"
import "core:strconv"
import "core:strings"

MAX_HEADER_BYTES :: 64 * 1024
MAX_BODY_BYTES :: 1024 * 1024
RECV_CHUNK :: 64 * 1024

Request :: struct {
	method: string,
	path:   string,
	body:   []byte,
}

Read_Error :: enum {
	None,
	Closed, // peer went away or socket error: nothing to answer
	Malformed, // 400
	Header_Too_Large, // 431
	Body_Too_Large, // 413
	Not_Implemented, // 501 (e.g. chunked transfer encoding)
}

Response :: struct {
	status:       int,
	content_type: string,
	allow:        string, // for 405 responses
	body:         []byte,
}

// Reads one HTTP/1.1 request from `sock`. All memory comes from `allocator`;
// the returned strings and body are views into that memory.
read_request :: proc(sock: net.TCP_Socket, allocator := context.allocator) -> (req: Request, err: Read_Error) {
	buf := make([dynamic]byte, 0, 4096, allocator)
	chunk: [RECV_CHUNK]byte

	header_end := -1
	for header_end < 0 {
		n, rerr := net.recv_tcp(sock, chunk[:])
		if rerr != nil || n == 0 {
			return {}, .Closed
		}
		search_from := max(0, len(buf) - 3)
		append(&buf, ..chunk[:n])
		if i := bytes.index(buf[search_from:], {'\r', '\n', '\r', '\n'}); i >= 0 {
			header_end = search_from + i
		} else if len(buf) > MAX_HEADER_BYTES {
			return {}, .Header_Too_Large
		}
	}
	if header_end > MAX_HEADER_BYTES {
		return {}, .Header_Too_Large
	}

	head := string(buf[:header_end])
	request_line, _, rest := strings.partition(head, "\r\n")

	parts := strings.split_n(request_line, " ", 3, allocator)
	if len(parts) != 3 || parts[0] == "" || parts[1] == "" || !strings.has_prefix(parts[2], "HTTP/") {
		return {}, .Malformed
	}
	req.method = parts[0]
	req.path = parts[1]

	content_length := 0
	has_length := false
	for line in strings.split_iterator(&rest, "\r\n") {
		name, sep, value := strings.partition(line, ":")
		if sep == "" {
			return {}, .Malformed
		}
		value = strings.trim_space(value)
		switch {
		case strings.equal_fold(name, "Content-Length"):
			n, ok := strconv.parse_int(value, 10)
			if !ok || n < 0 || (has_length && n != content_length) {
				return {}, .Malformed
			}
			content_length, has_length = n, true
		case strings.equal_fold(name, "Transfer-Encoding"):
			if !strings.equal_fold(value, "identity") {
				return {}, .Not_Implemented
			}
		}
	}
	if content_length > MAX_BODY_BYTES {
		return {}, .Body_Too_Large
	}

	body_start := header_end + 4
	total := body_start + content_length
	if len(buf) < total {
		reserve(&buf, total)
		for len(buf) < total {
			n, rerr := net.recv_tcp(sock, chunk[:min(len(chunk), total - len(buf))])
			if rerr != nil || n == 0 {
				return {}, .Closed
			}
			append(&buf, ..chunk[:n])
		}
	}
	req.body = buf[body_start:total]
	return req, .None
}

status_text :: proc(status: int) -> string {
	switch status {
	case 200: return "OK"
	case 201: return "Created"
	case 204: return "No Content"
	case 400: return "Bad Request"
	case 404: return "Not Found"
	case 405: return "Method Not Allowed"
	case 413: return "Payload Too Large"
	case 431: return "Request Header Fields Too Large"
	case 500: return "Internal Server Error"
	case 501: return "Not Implemented"
	}
	return "Unknown"
}

write_response :: proc(sock: net.TCP_Socket, res: Response) {
	b := strings.builder_make(0, 256, context.temp_allocator)
	strings.write_string(&b, "HTTP/1.1 ")
	strings.write_int(&b, res.status)
	strings.write_byte(&b, ' ')
	strings.write_string(&b, status_text(res.status))
	strings.write_string(&b, "\r\nConnection: close\r\n")
	if res.content_type != "" {
		strings.write_string(&b, "Content-Type: ")
		strings.write_string(&b, res.content_type)
		strings.write_string(&b, "\r\n")
	}
	if res.allow != "" {
		strings.write_string(&b, "Allow: ")
		strings.write_string(&b, res.allow)
		strings.write_string(&b, "\r\n")
	}
	// 204 must not carry a body; every other status gets an explicit length.
	if res.status != 204 {
		strings.write_string(&b, "Content-Length: ")
		strings.write_int(&b, len(res.body))
		strings.write_string(&b, "\r\n")
	}
	strings.write_string(&b, "\r\n")

	if len(res.body) > 0 && len(res.body) <= 16 * 1024 {
		// Small bodies go out in a single write.
		strings.write_bytes(&b, res.body)
		_, _ = net.send_tcp(sock, b.buf[:])
		return
	}
	if _, err := net.send_tcp(sock, b.buf[:]); err != nil {
		return
	}
	if len(res.body) > 0 {
		_, _ = net.send_tcp(sock, res.body)
	}
}

package main

import "core:fmt"
import "core:net"
import "core:os"
import "core:strconv"
import "core:strings"
import "core:sys/posix"
import "core:thread"
import "core:time"

// Each worker blocks in accept() on the shared listening socket, so this is
// also the number of connections served concurrently.
WORKER_COUNT :: 128
CLIENT_TIMEOUT :: 30 * time.Second

Server :: struct {
	listener: net.TCP_Socket,
	store:    Store,
}

main :: proc() {
	if len(os.args) != 2 {
		fmt.eprintfln("usage: %s <port>", os.args[0])
		os.exit(2)
	}
	port, ok := strconv.parse_int(os.args[1], 10)
	if !ok || port < 1 || port > 65535 {
		fmt.eprintfln("invalid port: %q", os.args[1])
		os.exit(2)
	}

	// A peer closing early must surface as a send error, not kill the process.
	posix.signal(.SIGPIPE, auto_cast posix.SIG_IGN)

	server: Server
	store_init(&server.store)
	defer store_destroy(&server.store)

	endpoint := net.Endpoint{address = net.IP4_Loopback, port = port}
	listener, err := net.listen_tcp(endpoint, backlog = 1024)
	if err != nil {
		fmt.eprintfln("listen on %v failed: %v", net.endpoint_to_string(endpoint, context.temp_allocator), err)
		os.exit(1)
	}
	defer net.close(listener)
	server.listener = listener

	workers: [WORKER_COUNT]^thread.Thread
	for &w in workers {
		w = thread.create_and_start_with_poly_data(&server, worker)
	}
	thread.join_multiple(..workers[:])
	for w in workers {
		thread.destroy(w)
	}
}

worker :: proc(server: ^Server) {
	for {
		client, _, err := net.accept_tcp(server.listener)
		if err != nil {
			if err == .Would_Block || err == .Interrupted || err == .Aborted {
				continue
			}
			// Typically fd exhaustion; back off instead of spinning.
			time.sleep(10 * time.Millisecond)
			continue
		}
		serve_connection(server, client)
		free_all(context.temp_allocator)
	}
}

serve_connection :: proc(server: ^Server, client: net.TCP_Socket) {
	defer net.close(client)
	_ = net.set_option(client, .Receive_Timeout, CLIENT_TIMEOUT)
	_ = net.set_option(client, .Send_Timeout, CLIENT_TIMEOUT)

	req, rerr := read_request(client, context.temp_allocator)
	res: Response
	switch rerr {
	case .None:
		res = route(&server.store, req)
	case .Closed:
		return
	case .Malformed:
		res = {status = 400}
	case .Header_Too_Large:
		res = {status = 431}
	case .Body_Too_Large:
		res = {status = 413}
	case .Not_Implemented:
		res = {status = 501}
	}
	write_response(client, res)
}

route :: proc(store: ^Store, req: Request) -> Response {
	KV_PREFIX :: "/kv/"

	switch {
	case req.path == "/health":
		if req.method != "GET" {
			return {status = 405, allow = "GET"}
		}
		return {status = 200, content_type = "text/plain", body = transmute([]byte)string("ok")}

	case req.path == "/kv":
		if req.method != "GET" {
			return {status = 405, allow = "GET"}
		}
		return list_keys(store)

	case strings.has_prefix(req.path, KV_PREFIX):
		key := req.path[len(KV_PREFIX):]
		if !valid_key(key) {
			return {status = 400}
		}
		switch req.method {
		case "GET":
			value, found := store_get(store, key, context.temp_allocator)
			if !found {
				return {status = 404}
			}
			return {status = 200, content_type = "application/octet-stream", body = value}
		case "PUT":
			switch store_put(store, key, req.body) {
			case .Created:
				return {status = 201}
			case .Replaced:
				return {status = 200}
			}
		case "DELETE":
			return {status = 204 if store_delete(store, key) else 404}
		}
		return {status = 405, allow = "GET, PUT, DELETE"}
	}
	return {status = 404}
}

list_keys :: proc(store: ^Store) -> Response {
	keys := store_keys(store, context.temp_allocator)

	b := strings.builder_make(context.temp_allocator)
	strings.write_byte(&b, '[')
	for k, i in keys {
		if i > 0 {
			strings.write_byte(&b, ',')
		}
		// Valid keys never contain characters that need JSON escaping.
		strings.write_byte(&b, '"')
		strings.write_string(&b, k)
		strings.write_byte(&b, '"')
	}
	strings.write_byte(&b, ']')
	return {status = 200, content_type = "application/json", body = b.buf[:]}
}

valid_key :: proc(key: string) -> bool {
	if len(key) < 1 || len(key) > 64 {
		return false
	}
	for c in transmute([]byte)key {
		switch c {
		case 'A' ..= 'Z', 'a' ..= 'z', '0' ..= '9', '_', '-':
		case:
			return false
		}
	}
	return true
}

package main

import "base:runtime"
import "core:slice"
import "core:strings"
import "core:sync"

// Thread-safe in-memory key-value store. Keys and values are owned by the
// store and live on the (thread-safe) heap allocator, independent of whatever
// allocator the calling request handler has in its context.
Store :: struct {
	lock:  sync.RW_Mutex,
	items: map[string][]byte,
}

store_init :: proc(s: ^Store) {
	s.items = make(map[string][]byte, runtime.heap_allocator())
}

store_destroy :: proc(s: ^Store) {
	for k, v in s.items {
		delete(k, runtime.heap_allocator())
		delete(v, runtime.heap_allocator())
	}
	delete(s.items)
}

Put_Result :: enum {
	Created,
	Replaced,
}

store_put :: proc(s: ^Store, key: string, value: []byte) -> Put_Result {
	// Copy outside the lock so large values do not stall other requests.
	owned := slice.clone(value, runtime.heap_allocator())

	sync.rw_mutex_lock(&s.lock)
	defer sync.rw_mutex_unlock(&s.lock)

	if old, ok := &s.items[key]; ok {
		delete(old^, runtime.heap_allocator())
		old^ = owned
		return .Replaced
	}
	s.items[strings.clone(key, runtime.heap_allocator())] = owned
	return .Created
}

// Returns a copy of the stored value made with `allocator`.
store_get :: proc(s: ^Store, key: string, allocator := context.allocator) -> (value: []byte, found: bool) {
	sync.rw_mutex_shared_lock(&s.lock)
	defer sync.rw_mutex_shared_unlock(&s.lock)

	v := s.items[key] or_return
	return slice.clone(v, allocator), true
}

store_delete :: proc(s: ^Store, key: string) -> bool {
	sync.rw_mutex_lock(&s.lock)
	defer sync.rw_mutex_unlock(&s.lock)

	if key not_in s.items {
		return false
	}
	k, v := delete_key(&s.items, key)
	delete(k, runtime.heap_allocator())
	delete(v, runtime.heap_allocator())
	return true
}

// Returns all keys sorted ascending, cloned with `allocator`.
store_keys :: proc(s: ^Store, allocator := context.allocator) -> []string {
	keys: []string
	{
		sync.rw_mutex_shared_lock(&s.lock)
		defer sync.rw_mutex_shared_unlock(&s.lock)

		keys = make([]string, len(s.items), allocator)
		i := 0
		for k in s.items {
			keys[i] = strings.clone(k, allocator)
			i += 1
		}
	}
	slice.sort(keys)
	return keys
}
